use js_runtime::{Runtime,Value,JsError,JsResult,EnvId};
fn method(rt:&mut Runtime,object:Value,name:&str,args:&[Value])->JsResult<Value>{let key=rt.string(name);let f=rt.get(object,key)?;rt.call(f,object,args)}
fn global(rt:&mut Runtime,name:&str)->Value{rt.lookup(rt.global_env,name).unwrap()}
fn texts(rt:&Runtime,values:Vec<Value>)->Vec<String>{values.into_iter().map(|v|if let Value::String(id)=v{rt.string_text(id)}else{panic!("not a property name")}).collect()}
fn receiver_x(rt:&mut Runtime,this:Value,_:&[Value],_:EnvId)->JsResult<Value>{let key=rt.string("x");rt.get(this,key)}
fn throw_assigned(_: &mut Runtime,_:Value,args:&[Value],_:EnvId)->JsResult<Value>{Err(JsError::Throw(args[0]))}
fn count_number(rt:&mut Runtime,_:Value,_:&[Value],_:EnvId)->JsResult<Value>{let global=Value::Object(rt.global_object);let key=rt.string("coercions");let previous=rt.get(global,key)?;let n=if let Value::Number(n)=previous{n}else{0.0};rt.set(global,key,Value::Number(n+1.0),true)?;Ok(Value::Number(2.0))}
fn throw_type(_: &mut Runtime,_:Value,_:&[Value],_:EnvId)->JsResult<Value>{Err(JsError::TypeError("actual getter failure".into()))}
#[test]
fn inherited_accessors_receive_original_receiver_and_throw_identity_survives(){let mut rt=Runtime::new();let prototype=rt.object();let target=rt.object();rt.set_prototype(target,prototype).unwrap();let x=rt.string("x");rt.define_data(target,x,Value::Number(37.0),true,true,true).unwrap();let get=rt.native_function("get",0,receiver_x).unwrap();let set=rt.native_function("set",1,throw_assigned).unwrap();let key=rt.string("accessor");rt.define_accessor(prototype,key,Some(get),Some(set),true,true).unwrap();assert_eq!(rt.get(target,key).unwrap(),Value::Number(37.0));let sentinel=rt.object();assert_eq!(rt.set(target,key,sentinel,false),Err(JsError::Throw(sentinel)));}
#[test]
fn readonly_prototype_rejects_without_shadowing_and_same_value_is_descriptor_specific(){let mut rt=Runtime::new();let prototype=rt.object();let target=rt.object();rt.set_prototype(target,prototype).unwrap();let key=rt.string("x");rt.define_data(prototype,key,Value::Number(-0.0),false,true,false).unwrap();rt.set(target,key,Value::Number(4.0),false).unwrap();assert!(!rt.has_own_property(target,key).unwrap());assert!(matches!(rt.set(target,key,Value::Number(4.0),true),Err(JsError::TypeError(_))));assert!(rt.define_data(prototype,key,Value::Number(0.0),false,true,false).is_err());let value=rt.get(target,key).unwrap();assert!(matches!(value,Value::Number(n)if n.to_bits()==(-0.0_f64).to_bits()));}
#[test]
fn array_length_shrink_keeps_failure_prefix_in_sloppy_mode(){let mut rt=Runtime::new();let array=rt.array(&[Some(Value::Number(0.0)),Some(Value::Number(1.0)),Some(Value::Number(2.0)),Some(Value::Number(3.0))]);let key=rt.string("2");rt.define_data(array,key,Value::Number(2.0),true,true,false).unwrap();let length=rt.string("length");rt.set(array,length,Value::Number(0.0),false).unwrap();assert_eq!(rt.get(array,length).unwrap(),Value::Number(3.0));let key=rt.string("3");assert!(!rt.has_own_property(array,key).unwrap());}
#[test]
fn array_length_converts_twice_and_does_not_swallow_conversion_type_errors(){let mut rt=Runtime::new();let array=rt.array(&[]);let number=rt.object();let function=rt.native_function("valueOf",0,count_number).unwrap();let key=rt.string("valueOf");rt.define_data(number,key,function,true,true,true).unwrap();let length=rt.string("length");rt.set(array,length,number,false).unwrap();let key=rt.string("coercions");assert_eq!(rt.get(Value::Object(rt.global_object),key).unwrap(),Value::Number(2.0));let fail=rt.native_function("valueOf",0,throw_type).unwrap();let key=rt.string("valueOf");rt.set(number,key,fail,true).unwrap();assert_eq!(rt.set(array,length,number,false),Err(JsError::TypeError("actual getter failure".into())));}
#[test]
fn indexed_keys_precede_strings_and_intrinsic_length_retains_creation_order(){let mut rt=Runtime::new();let array=rt.array(&[None,Some(Value::Number(2.0))]);let key=rt.string("z");rt.set(array,key,Value::Number(1.0),false).unwrap();let keys=rt.own_keys(array,false).unwrap();assert_eq!(texts(&rt,keys),["1","length","z"]);let object=rt.object();for name in ["2","01","1","z"]{let key=rt.string(name);rt.set(object,key,Value::Null,true).unwrap();}let keys=rt.own_keys(object,true).unwrap();assert_eq!(texts(&rt,keys),["1","2","01","z"]);}
#[test]
fn utf16_string_indices_and_names_preserve_lone_surrogates(){let mut rt=Runtime::new();let text=rt.string_utf16(&[0xd800,0x61]);let key=rt.string("0");let first=rt.get(text,key).unwrap();assert!(matches!(first,Value::String(id)if rt.string_units(id)==[0xd800]));let boxed=rt.to_object(text).unwrap();rt.define_data(boxed,key,first,false,true,false).unwrap();let keys=rt.own_keys(boxed,false).unwrap();assert_eq!(texts(&rt,keys),["0","1","length"]);assert!(!rt.delete(text,key,false).unwrap());assert!(rt.delete(text,key,true).is_err());}
#[test]
fn v8_sort_compacts_undefined_and_holes_with_live_property_writeback(){let mut rt=Runtime::new();let array=rt.array(&[Some(Value::Number(3.0)),None,Some(Value::Undefined),Some(Value::Number(1.0))]);method(&mut rt,array,"sort",&[]).unwrap();let key=rt.string("0");assert_eq!(rt.get(array,key).unwrap(),Value::Number(1.0));let key=rt.string("1");assert_eq!(rt.get(array,key).unwrap(),Value::Number(3.0));let key=rt.string("2");assert!(rt.has_own_property(array,key).unwrap());assert_eq!(rt.get(array,key).unwrap(),Value::Undefined);let key=rt.string("3");assert!(!rt.has_own_property(array,key).unwrap());}
#[test]
fn cyclic_join_is_bounded_and_global_constructors_are_real_callable_values(){let mut rt=Runtime::new();let array=rt.array(&[]);method(&mut rt,array,"push",&[array]).unwrap();let result=method(&mut rt,array,"join",&[]).unwrap();assert!(matches!(result,Value::String(id)if rt.string_units(id).is_empty()));let array_constructor=global(&mut rt,"Array");let array=rt.construct(array_constructor,&[Value::Number(3.0)]).unwrap();let key=rt.string("length");assert_eq!(rt.get(array,key).unwrap(),Value::Number(3.0));let number=global(&mut rt,"Number");assert_eq!(rt.call(number,Value::Undefined,&[]).unwrap(),Value::Number(0.0));}
